import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/social_fund_record.dart';
import '../../../data/repositories/group_repository.dart';
import '../../widgets/app_drawer.dart';
class SocialFundScreen extends StatelessWidget{const SocialFundScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();return Scaffold(appBar:AppBar(title:const Text('Social Fund')),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Emergency Assistance Records',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.socialFund(),builder:(c,s)=>Column(children:(s.data??[]).map((x)=>Card(child:ListTile(title:Text(x.toString()),subtitle:Text('Digital record')))).toList()))]));} void _add(BuildContext context,GroupRepository repo){final member=TextEditingController();final amount=TextEditingController();final type=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Contribution / Withdrawal'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:member,decoration:const InputDecoration(labelText:'Member / Description / Agenda')),TextField(controller:amount,decoration:const InputDecoration(labelText:'Amount / Decisions'),keyboardType:TextInputType.number),TextField(controller:type,decoration:const InputDecoration(labelText:'Type'))]),actions:[FilledButton(onPressed:(){repo.addSocialFund(SocialFundRecord(id:'',type:type.text.isEmpty?"contribution":type.text,amount:double.tryParse(amount.text)??0,description:member.text,date:DateTime.now()));Navigator.pop(context);},child:const Text('Save'))]));}}
